import {renderCloudDocuments} from './cloud-documents.js';
export function renderSettings(api,page){
  const {shell,breadcrumb,title,panel,field,select,icon,box,notice,link,action,toggle,e,profile,stored,set,$,toast,modal}=api;
  const buttonRow=(text)=>`<div class="d-form-actions">${link('Back to Profile','profile','outline')}<button class="btn" type="submit">${text}</button></div>`;
  function saveForm(id,key,message){$(id).onsubmit=event=>{event.preventDefault();const form=event.currentTarget,fd=new FormData(form),result={};for(const [k,v] of fd)result[k]=v;for(const input of form.querySelectorAll('input[type=checkbox]'))result[input.name]=input.checked;set(key,result);toast(message)}}
  const intro=(name,sub)=>breadcrumb(name)+title(name,sub);
  if(page==='profile'){
    const shortcuts=[['95ff5.svg','Vehicle Subscription','Update your vehicle preferences and subscription details.','vehicle'],['1836d.svg','Payment Details','Manage your payment methods and payout settings.','payment'],['4bbbe.svg','Notification Settings','Control how and when you receive notifications.','notifications'],['6c563.svg','Documents & Verification','Upload and manage your verification documents.','documents']];
    shell(`${intro('Profile','Manage your personal and contact information.')}<div class="d-stack"><section class="d-card d-profile-banner"><div class="d-initials">${e(profile.firstName[0]||'D')}${e(profile.lastName[0]||'')}</div><div><h2>${e(profile.firstName)} ${e(profile.lastName)} <span class="d-badge approved">Active</span></h2><p>365 Trucking Driver</p><button class="btn" type="button" id="d-edit-profile">${icon('938e0.svg')} Edit Profile</button> <button type="button" id="d-password-info">Change Password</button></div></section><form id="d-profile-form" class="d-stack">${panel('Personal Information',`<div class="d-form-grid">${field('First Name','firstName',profile.firstName,'text','required readonly')}${field('Last Name','lastName',profile.lastName,'text','required readonly')}${field('Date of Birth','dob',profile.dob,'date','readonly')}${field('Gender','gender',profile.gender,'text','readonly')}${field('National ID / License Number','license',profile.license,'text','readonly')}${field('License Expiry Date','expiry',profile.expiry,'date','readonly')}</div><p class="d-field-note">This information is used for verification and compliance purposes. Sample data only.</p>`)}${panel('Contact Information',`<div class="d-form-grid">${field('Email','email',profile.email,'email','required readonly')}${field('Phone Number','phone',profile.phone,'tel','readonly')}${field('City / Region','city',profile.city,'text','readonly')}${field('Full Address','address',profile.address,'text','readonly')}</div><p class="d-field-note">Make sure your contact details are always up to date.</p><div id="d-profile-save" hidden>${buttonRow('Save Profile')}</div>`)}</form>${panel('Account Summary',`<div class="d-summary-grid">${[['36ad5.svg','Total Completed Jobs','247'],['d7879.svg','Rating','4.8 / 5.0'],['ee570.svg','Member Since','March 2023'],['0b137.svg','Total Earnings','$28,450']].map(x=>`<div>${icon(x[0])}<small>${x[1]}</small><strong>${x[2]}</strong></div>`).join('')}</div><p class="d-auth-note">Illustrative account history from the design.</p>`)}${panel('Settings & Shortcuts',`<div class="d-shortcuts">${shortcuts.map(x=>`<a class="d-shortcut" href="#/driver/${x[3]}">${box(x[0])}<div><strong>${x[1]}</strong><small>${x[2]}</small></div><span>›</span></a>`).join('')}</div>`)}</div>`,{settings:true});
    $('#d-edit-profile').onclick=()=>{$('#d-profile-form').querySelectorAll('input').forEach(i=>i.readOnly=false);$('#d-profile-save').hidden=false;$('#d-firstName').focus();toast('Edit the sample details, then save your profile.')};
    $('#d-password-info').onclick=()=>modal('Demo sign-in','Authentication is not connected. Passwords are never saved or changed in this prototype.');
    $('#d-profile-form').onsubmit=event=>{event.preventDefault();const fd=new FormData(event.currentTarget);set('365-driver-profile',{...profile,...Object.fromEntries(fd)});event.currentTarget.querySelectorAll('input').forEach(i=>i.readOnly=true);$('#d-profile-save').hidden=true;toast('Driver profile saved in this browser.')};return;
  }
  if(page==='vehicle'){
    const prefs=stored('365-driver-vehicle',{primary:'Cargo Van',cargo:true,pickup:true,car:true,Downtown:true,'North District':true,'East Side':true,urgent:true});
    shell(`${intro('Vehicle Subscription','Choose which vehicle types you want to receive projects for.')}${notice('About Vehicle Subscription','<p>You can choose to accept projects compatible with your vehicle.</p><p>Selecting larger vehicles may reduce the number of available projects but increase the average payout.</p><p>Your preferences can be updated at any time to match your current availability.</p>','','b04d6.svg')}<form id="d-vehicle-form">${panel('Vehicle Preferences',`${select('Primary vehicle you are driving','primary',['Cargo Van','Box Truck','Pickup Truck','Car / Sedan','Motorcycle'],prefs.primary)}<p class="d-auth-note">This defines the main type of delivery projects you can accept.</p><h3 style="margin-top:32px;font-size:14px">Accept projects from</h3>${[['cargo','Cargo Van','73178.svg'],['truck','Box Truck','1399d.svg'],['pickup','Pickup Truck','13ba7.svg'],['car','Car / Sedan','4b1b4.svg'],['motorcycle','Motorcycle','5d640.svg']].map(x=>`<label class="d-choice-row"><input type="checkbox" name="${x[0]}" ${prefs[x[0]]?'checked':''}>${box(x[2])}<span>${x[1]}</span></label>`).join('')}<p class="d-auth-note">You can accept projects that match or are smaller than your primary vehicle capacity.</p><h3 style="margin-top:32px;font-size:14px">Preferred service areas</h3><div class="d-chips">${['Downtown','North District','East Side','West End','South Bay','Airport Area'].map(x=>`<label><input type="checkbox" name="${x}" ${prefs[x]?'checked':''}>${x}</label>`).join('')}</div><p class="d-auth-note">Select the areas where you are available to work.</p><div class="d-toggle-row"><div><strong>Available for urgent/same-day jobs</strong><small>Receive notifications for time-sensitive deliveries with higher payouts.</small></div>${toggle('urgent','Available for urgent jobs',prefs.urgent)}</div>${buttonRow('Save Preferences')}`)}</form>${notice('Important','<ul><li>Changing your vehicle subscription may affect the types of jobs you receive.</li><li>Make sure your vehicle information is accurate and verified.</li><li>Ensure your registration and insurance documents are up to date.</li></ul>','yellow','3a309.svg')}<p class="d-demo">Preferences are saved locally. Live job matching is not connected.</p>`,{settings:true});
    saveForm('#d-vehicle-form','365-driver-vehicle','Vehicle preferences saved in this browser.');return;
  }
  if(page==='payment'){
    const prefs=stored('365-driver-payout',{holder:profile.firstName+' '+profile.lastName,frequency:'Weekly - Every Friday'});
    shell(`${intro('Payment Details','Manage your payment methods and payout settings.')}${notice('Payment Settings Preview','<p>This prototype shows masked sample payment details. Do not enter a real bank account. Actual payouts will require a secure payment provider.</p>','','edbe9.svg')}<form id="d-payment-form">${panel('Bank Account Information',`<div class="d-stack">${field('Account Holder Name','holder',prefs.holder,'text','required')}<div class="field"><label>Routing Number</label><input aria-label="Sample routing number" value="••••••021" readonly><small>Masked sample routing number.</small></div><div class="field"><label>Account Number</label><input aria-label="Sample bank account" value="****5678" readonly><small>No bank details are stored by this prototype.</small></div>${select('Payout Frequency','frequency',['Daily - Every business day','Weekly - Every Friday','Monthly - First business day'],prefs.frequency)}<div class="d-info blue" style="margin:0"><div><h3>Current Payout Schedule</h3><p>Frequency: ${e(prefs.frequency)}</p><p>Next Payout: Preview only</p><p>Pending Balance: $245.00 (sample)</p></div></div></div>${buttonRow('Save Payout Preferences')}`)}</form>${notice('Important Information','<ul><li>Production changes require verified payment-provider access.</li><li>Bank account verification and real payouts are not connected.</li><li>Only a sample account name and payout preference are saved locally.</li></ul>','yellow','a5d73.svg')}`,{settings:true});saveForm('#d-payment-form','365-driver-payout','Demo payout preferences saved. No banking details were changed.');return;
  }
  if(page==='notifications'){
    const prefs=stored('365-driver-notifications',{}),rows=[['jobs','Job Request Alerts','Get notified when new delivery jobs matching your preferences become available.'],['payments','Payment Alerts','Receive updates about earnings, payouts, and payment confirmations.'],['account','Account Updates','Important notifications about your account, profile changes, and security alerts.'],['offers','Promotions & Bonuses','Stay informed about special promotions, bonus opportunities, and referral rewards.']];
    shell(`${intro('Notification Settings','Control how and when you receive notifications.')}${notice('Stay Informed','<p>Customize your notification preferences to stay updated on new job opportunities, payment updates, and important account changes.</p><p>You can choose email, SMS, or push preferences for the future connected app.</p>','purple','4bbbe.svg')}<form id="d-notification-form">${panel('Notification Preferences',`<div style="overflow:auto"><table class="d-notification-table"><thead><tr><th>Notification Type</th><th>Email</th><th>SMS</th><th>Push</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td><strong>${x[1]}</strong><small>${x[2]}</small></td>${['email','sms','push'].map((channel,j)=>`<td>${toggle(x[0]+'-'+channel,x[1]+' via '+channel,prefs[x[0]+'-'+channel]??(i===0||i===1&&j!==1||i===2&&j===0))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="d-note-panel" style="background:#f9fafb"><h3>Quiet Hours</h3><p class="muted">Pause non-urgent notifications during specific hours.</p><div class="d-form-grid" style="margin-top:16px">${field('From','from',prefs.from||'22:00','time')}${field('To','to',prefs.to||'07:00','time')}</div></div>${buttonRow('Save Notification Preferences')}`)}</form>${notice('Important Information','<ul><li>These settings are stored only on this device.</li><li>Email, SMS, and push delivery are not connected.</li><li>No browser notification permission is requested by this prototype.</li></ul>','yellow','a5d73.svg')}`,{settings:true});saveForm('#d-notification-form','365-driver-notifications','Notification preferences saved in this browser.');return;
  }
  if(page==='documents'){
    shell(breadcrumb('Documents & Verification')+title('Documents & Verification','Upload your verification files for admin review.')+'<div id="driver-cloud-documents"></div>',{settings:true});
    renderCloudDocuments(document.getElementById('driver-cloud-documents'));return;
  }
}
